# Help trees: WWW\help\<product>\ holds Markdown (front matter + body) and an optional index.json.
# Each .md becomes /help/<product>/<path-without-.md>/ ; <product>\index.md is /help/<product>/ ;
# other files (images) are copied to the same relative path. help\dl\ is generated by featuregen
# (never edit it); help\yadf\ is delivered by the YADF team.
. (Join-Path $PSScriptRoot 'Markdown.ps1')

# Final URL of a link/image target found in the source file $SrcRel (tree-relative, '/'-separated).
function Resolve-HelpHref([string]$Href, [string]$Product, [string]$SrcRel) {
    if ($Href -match '^([a-zA-Z][\w+.-]*:|//|/|#)') { return $Href }
    $anchor = ''
    $ix = $Href.IndexOf('#')
    if ($ix -ge 0) { $anchor = $Href.Substring($ix); $Href = $Href.Substring(0, $ix) }
    $dir = if ($SrcRel.Contains('/')) { $SrcRel.Substring(0, $SrcRel.LastIndexOf('/')) } else { '' }
    $parts = [Collections.Generic.List[string]]::new()
    foreach ($seg in @($dir.Split('/')) + @($Href.Split('/'))) {
        if ($seg -eq '' -or $seg -eq '.') { continue }
        if ($seg -eq '..') { if ($parts.Count) { $parts.RemoveAt($parts.Count - 1) }; continue }
        $parts.Add($seg)
    }
    $rel = $parts -join '/'
    $base = "/help/$Product/"
    if ($rel -match '\.md$') {
        $rel = $rel.Substring(0, $rel.Length - 3)
        if ($rel -eq 'index') { return $base + $anchor }
        if ($rel.EndsWith('/index')) { $rel = $rel.Substring(0, $rel.Length - 6) }
        return "$base$rel/$anchor"
    }
    $base + $rel + $anchor
}

# One entry per help tree found under $HelpRoot (a folder with an index.md).
# Page: Path, Title, Summary, Main (html). File: published asset (SrcFull, Rel).
function Get-HelpTrees([string]$HelpRoot) {
    if (-not (Test-Path -LiteralPath $HelpRoot)) { return @() }
    foreach ($dir in Get-ChildItem -LiteralPath $HelpRoot -Directory | Sort-Object Name) {
        if (-not (Test-Path -LiteralPath (Join-Path $dir.FullName 'index.md'))) { continue }
        $product = $dir.Name
        $root = $dir.FullName.TrimEnd('\')
        $idx = Split-FrontMatter ([IO.File]::ReadAllText((Join-Path $root 'index.md')))
        $treeTitle = if ($idx.Meta['title']) { $idx.Meta['title'] } else { "$product help" }
        $json = $null
        $jp = Join-Path $root 'index.json'
        if (Test-Path -LiteralPath $jp) { $json = [IO.File]::ReadAllText($jp) | ConvertFrom-Json }
        $pages = [Collections.Generic.List[object]]::new()
        $files = [Collections.Generic.List[object]]::new()
        foreach ($f in Get-ChildItem -LiteralPath $root -Recurse -File) {
            $rel = $f.FullName.Substring($root.Length + 1).Replace('\', '/')
            if ($f.Extension -in '.png', '.jpg', '.jpeg', '.gif', '.svg') { $files.Add(@{ SrcFull = $f.FullName; Rel = "$product/$rel" }); continue }
            if ($f.Extension -ne '.md') { continue }
            $doc = Split-FrontMatter ([IO.File]::ReadAllText($f.FullName))
            $m = $doc.Meta
            $ctx = @{ Product = $product; SrcRel = $rel; ResolveHref = { param($h, $c) Resolve-HelpHref $h $c.Product $c.SrcRel } }
            $body = ConvertFrom-SiteMarkdown $doc.Body $ctx
            $isRoot = ($rel -eq 'index.md')
            $path = if ($isRoot) { "/help/$product/" } else { "/help/$product/" + $rel.Substring(0, $rel.Length - 3) + '/' }
            $title = if ($m['title']) { $m['title'] } else { $f.BaseName }
            $facts = foreach ($k in @(@('since', 'Since'), @('default', 'Default'), @('ini', 'INI key'), @('cli', 'CLI flag'))) {
                if ($m[$k[0]]) { "$($k[1]): <code>$(ConvertTo-HtmlText $m[$k[0]])</code>" }
            }
            if ($facts) {
                $line = "<p class=""meta facts"">" + ($facts -join ' &middot; ') + "</p>"
                $body = if ($body -match '</h1>') { [regex]::Replace($body, '</h1>\n?', "</h1>`n$line`n", 1) } else { $line + $body }
            }
            if ($isRoot -and $json -and $json.groups) {
                $g = [Text.StringBuilder]::new()
                foreach ($grp in @($json.groups | Sort-Object { [int]$_.order })) {
                    [void]$g.Append("<h2 id=""$(Get-MdSlug $grp.id)"">$(ConvertTo-HtmlText $grp.title)</h2><ul class=""list"">")
                    foreach ($o in @($json.options | Where-Object { $_.group -eq $grp.id } | Sort-Object { [int]$_.order })) {
                        $href = Resolve-HelpHref $o.file $product 'index.md'
                        [void]$g.Append("<li><a class=""title"" href=""$href"">$(ConvertTo-HtmlText $o.title)</a><p>$(ConvertTo-HtmlText $o.summary)</p></li>")
                    }
                    [void]$g.Append('</ul>')
                }
                $body += $g.ToString()
            }
            $crumb = if ($isRoot) { '' } else { "<p class=""meta""><a href=""/help/$product/"">$(ConvertTo-HtmlText $treeTitle)</a></p>" }
            $summary = if ($m['summary']) { $m['summary'] } else { $title }
            $pages.Add(@{ Path = $path; Title = $title; Summary = $summary; Main = "<div class=""page help"">$crumb$body</div>" })
        }
        [pscustomobject]@{ Product = $product; Title = $treeTitle; Summary = $idx.Meta['summary']; Pages = $pages.ToArray(); Files = $files.ToArray() }
    }
}
